import { useDialogDismiss } from './components/ui/dialog';
import { Disclosure } from './components/ui/disclosure';
import { useMotionRegion } from './lib/use-motion-region';
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { ArrowLeft, ArrowRight, BarChart3, CheckCheck, ChevronRight, CircleAlert, Download, FileSpreadsheet, History, Info, Upload, LoaderCircle, LockKeyhole, Pencil, Plus, Save, Send, Target } from 'lucide-react';
import { Button } from './components/ui/button';
import { Dialog } from './components/ui/dialog';
import { ApiError, api, patch, post, type Client, type User } from './lib/api';
import { indicatorMeta, rawMetricKeys, formatMetric, monthLabel, parseIndicatorDecimal, indicatorPreviewErrorsCsv, type MetricKey } from './lib/indicators';
import type { ActionPlan } from './Plans';

type Reason = 'missing_data' | 'zero_denominator' | 'basis_unconfirmed' | 'attribution_unconfirmed' | 'incomplete_costs' | string;
type Metric = { value: number | null; reason: Reason | null; unit: 'BRL' | 'count' | 'percent' | 'ratio' };
type Metrics = Partial<Record<MetricKey, Metric>>;
type IndicatorContent = { periodStatus: 'partial' | 'closed'; sourceLabel: string; notes?: string; basisConfirmed: boolean; adsAttributionConfirmed: boolean; costsComplete: boolean; values: Partial<Record<MetricKey, string | number | null>> };
type Snapshot = IndicatorContent & { version: number; publishedAt: string; metrics: Metrics };
type IndicatorRecord = { id: string; enrollmentId: string; enrollmentStatus: string; clientId: string; clientName: string; period: string; status: 'draft' | 'published' | 'archived'; sourceType: 'manual' | 'csv'; publishedVersion: number | null; published?: Snapshot | null; sourceLabel?: string; periodStatus?: 'partial' | 'closed'; metrics?: Metrics; draftVersion?: number; draft?: IndicatorContent; hasUnpublishedChanges?: boolean; revisions: { version: number; publishedAt: string }[]; history?: { id: string; action: string; createdAt: string; actorName?: string; details?: Record<string, unknown> }[] };
type Comparison = { comparable: boolean; reason?: string | null; metrics: Partial<Record<MetricKey, { current: number | null; previous: number | null; absoluteChange: number | null; percentChange: number | null; reason?: string | null }>> };
type GoalResult = { status: 'not_informed' | 'in_progress' | 'achieved' | 'not_achieved'; actual: number | null; target: number; difference: number | null; currentlyMeets: boolean | null; reason?: string | null };
type IndicatorGoal = { id: string; enrollmentId: string; enrollmentStatus?: string; clientName?: string; period: string; metricKey: MetricKey; target: string; direction: 'at_least' | 'at_most'; notes?: string; planId?: string | null; planTitle?: string; status: 'active' | 'archived'; version: number; evaluation?: GoalResult };
type EvolutionPoint = { period: string; recordId: string | null; publishedVersion: number | null; data: IndicatorContent | null; metrics: Metrics | null; comparison: Comparison | null; goals: IndicatorGoal[] };
type Evolution = { enrollmentId: string; from: string; to: string; points: EvolutionPoint[] };
type PageProps = { route: string; user: User; go: (path: string) => void; notify: (message: string) => void };
const reasonLabels: Record<string, string> = {
  missing_current_period: 'Este mês ainda não tem publicação.', non_adjacent_periods: 'A comparação exige o mês imediatamente anterior.', source_changed: 'A origem ou a base dos dados mudou entre os meses.', zero_baseline: 'O mês anterior tem valor zero; não há variação percentual calculável.', missing_data: 'Faltam dados para calcular.', zero_denominator: 'A base do cálculo é zero.', basis_unconfirmed: 'Confirme que os dados têm o mesmo escopo e base.', attribution_unconfirmed: 'Confirme a mesma janela de atribuição da publicidade.', incomplete_costs: 'Os custos totais ainda não estão completos.',
  missing_previous: 'O mês imediatamente anterior não tem publicação.', missing_previous_period: 'O mês imediatamente anterior não tem publicação.', missing_current: 'Este mês ainda não tem publicação.', partial_period: 'Um dos meses está parcial. A comparação exige dois meses fechados.', partial: 'Um dos meses está parcial. A comparação exige dois meses fechados.', source_mismatch: 'Os meses têm origens ou bases diferentes.', different_source: 'Os meses têm origens ou bases diferentes.', missing_record: 'Ainda não há resultado publicado.',
};
function reasonLabel(reason?: string | null) { return reason ? reasonLabels[reason] || 'Os dados disponíveis ainda não permitem esta comparação.' : 'Não informado'; }
function currentMonth() { const parts = new Intl.DateTimeFormat('en-CA', { year: 'numeric', month: '2-digit', timeZone: 'America/Sao_Paulo' }).formatToParts(new Date()); return `${parts.find(p => p.type === 'year')!.value}-${parts.find(p => p.type === 'month')!.value}`; }
function shiftMonth(period: string, amount: number) { const [year, month] = period.split('-').map(Number); return new Date(Date.UTC(year, month - 1 + amount, 1)).toISOString().slice(0, 7); }
function rangeError(from: string, to: string, allowFuture = false) { if (!/^[1-9]\d{3}-(0[1-9]|1[0-2])$/.test(from) || !/^[1-9]\d{3}-(0[1-9]|1[0-2])$/.test(to)) return 'Informe os meses inicial e final.'; if (from > to) return 'O mês inicial deve vir antes do mês final.'; const a = from.split('-').map(Number); const b = to.split('-').map(Number); if ((b[0] - a[0]) * 12 + b[1] - a[1] >= 36) return 'Escolha um intervalo de até 36 meses.'; if (!allowFuture && to > currentMonth()) return 'Os resultados podem ser consultados até o mês atual.'; return ''; }
function dateLabel(value?: string) { return value ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(new Date(value)) : 'Não informado'; }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function ErrorBox({ error }: { error: unknown }) { return error ? <div className="error-box" role="alert"><CircleAlert size={17} /><span>{error instanceof Error ? error.message : String(error)}</span></div> : null; }
function Loading() { return <div className="loading" role="status"><LoaderCircle className="spin" size={20} />Carregando indicadores…</div>; }
function Empty({ title, detail }: { title: string; detail: string }) { return <div className="empty"><div className="empty-icon"><BarChart3 size={25} /></div><h3>{title}</h3><p>{detail}</p></div>; }
function PeriodBadge({ value }: { value?: string }) { return value ? <span className={`badge ${value === 'closed' ? 'green' : 'amber'}`}>{value === 'closed' ? 'Mês fechado' : 'Parcial'}</span> : <span className="badge neutral">Sem publicação</span>; }

export function Indicators(props: PageProps) {
  const id = props.route.split('?')[0].split('/')[2];
  return id ? <RecordDetail key={id} {...props} id={id} /> : <IndicatorDashboard {...props} />;
}

function IndicatorDashboard({ route, user, go, notify }: PageProps) {
  const params = new URLSearchParams(route.split('?')[1]); const requestedEnrollment = params.get('enrollmentId') || '';
  const clients = useQuery({ queryKey: ['clients'], queryFn: () => api<Client[]>('/clients') });
  const enrollmentId = requestedEnrollment || clients.data?.[0]?.enrollmentId || '';
  const client = clients.data?.find(c => c.enrollmentId === enrollmentId);
  const initialPeriod = /^[1-9]\d{3}-(0[1-9]|1[0-2])$/.test(params.get('period') || '') ? params.get('period')! : currentMonth();
  const [from, setFrom] = useState(shiftMonth(initialPeriod, -5)); const [to, setTo] = useState(initialPeriod);
  const [tab, setTab] = useState(params.get('tab') === 'csv' && user.role !== 'mentee' ? 'csv' : params.get('goalId') ? 'goals' : 'evolution'); const [creating, setCreating] = useState(false); const [editingGoal, setEditingGoal] = useState<IndicatorGoal | 'new' | null>(null);
  useEffect(() => { const p = new URLSearchParams(route.split('?')[1]); const period = /^[1-9]\d{3}-(0[1-9]|1[0-2])$/.test(p.get('period') || '') ? p.get('period')! : currentMonth(); setFrom(shiftMonth(period, -5)); setTo(period); setTab(p.get('tab') === 'csv' && user.role !== 'mentee' ? 'csv' : p.get('goalId') ? 'goals' : 'evolution'); setCreating(false); setEditingGoal(null); }, [route]);
  const dashboardMotion = useMotionRegion(tab);
  const validation = rangeError(from, to, tab === 'goals');
  const evolution = useQuery({ queryKey: ['indicator-evolution', enrollmentId, from, to], queryFn: () => api<Evolution>(`/indicators/evolution?${new URLSearchParams({ enrollmentId, from, to })}`), enabled: !!client && !rangeError(from, to), refetchInterval: 30_000 });
  const records = useQuery({ queryKey: ['indicators', enrollmentId], queryFn: () => api<IndicatorRecord[]>(`/indicators?enrollmentId=${encodeURIComponent(enrollmentId)}`), enabled: !!client });
  const goals = useQuery({ queryKey: ['indicator-goals', enrollmentId], queryFn: () => api<IndicatorGoal[]>(`/indicator-goals?enrollmentId=${encodeURIComponent(enrollmentId)}`), enabled: !!client, refetchInterval: 30_000 });
  const canEdit = user.role !== 'mentee' && client?.status === 'active';
  const selected = evolution.data?.points.find(p => p.period === to);
  const scopedRecords = (records.data || []).filter(r => r.enrollmentId === enrollmentId && r.period >= from && r.period <= to);
  const scopedGoals = (goals.data || []).filter(g => g.enrollmentId === enrollmentId && g.period >= from && g.period <= to);
  return <div className="motion-region" ref={dashboardMotion}><div className="page-title"><div><span className="eyebrow">RESULTADOS DO NEGÓCIO, COM CONTEXTO</span><h1>Indicadores e metas</h1><p>Dados mensais informados pela equipe. A evolução do negócio acompanha o contexto da operação.</p></div>{canEdit && <Button onClick={() => setCreating(true)}><Plus />Registrar mês</Button>}</div><section className="panel indicator-context"><Field label="Empresa / contratação"><select value={enrollmentId} onChange={e => go(`/indicators?enrollmentId=${e.target.value}`)}><option value="" disabled>Selecione a contratação</option>{clients.data?.map(c => <option key={c.enrollmentId} value={c.enrollmentId}>{c.name} · {c.programName}</option>)}</select></Field><Field label="De"><input type="month" value={from} max={to} onChange={e => setFrom(e.target.value)} /></Field><Field label="Até"><input type="month" value={to} min={from} max={tab === 'goals' ? undefined : currentMonth()} onChange={e => setTo(e.target.value)} /></Field><p><Info size={15} />Uma empresa e uma base por mês. Intervalo de até 36 meses.</p></section><ErrorBox error={clients.error || validation} />{clients.isPending ? <Loading /> : clients.isError ? null : !client ? <Empty title="Selecione uma contratação disponível" detail="O painel mostra somente empresas às quais você tem acesso." /> : <><div className="tabs indicator-tabs"><button className={tab === 'evolution' ? 'selected' : ''} onClick={() => setTab('evolution')}><BarChart3 size={14} />Evolução mensal</button><button className={tab === 'records' ? 'selected' : ''} onClick={() => setTab('records')}>Registros mensais</button><button className={tab === 'goals' ? 'selected' : ''} onClick={() => setTab('goals')}><Target size={14} />Metas</button>{user.role !== 'mentee' && <button className={tab === 'csv' ? 'selected' : ''} onClick={() => go(`/indicators?enrollmentId=${enrollmentId}&tab=csv`)}><FileSpreadsheet size={14} />Importar CSV</button>}</div>{!validation && tab === 'evolution' && <><ErrorBox error={evolution.error} />{evolution.isPending ? <Loading /> : !evolution.isError && evolution.data && <><div className="indicator-month-heading"><div><span className="eyebrow">RETRATO DO MÊS</span><h2>{monthLabel(to)}</h2><p>{selected?.data?.sourceLabel || 'Nenhum resultado publicado para este mês.'}</p></div><PeriodBadge value={selected?.data?.periodStatus} /></div><div className="indicator-stats">{(['revenue', 'orders', 'conversionRate', 'estimatedMargin'] as MetricKey[]).map(key => <MetricCard key={key} metricKey={key} point={selected} />)}</div><EvolutionChart points={evolution.data.points} go={go} exportUrl={`/api/indicators/evolution/export.csv?${new URLSearchParams({ enrollmentId, from, to })}`} /><p className="indicator-disclaimer"><Info size={15} />Os valores descrevem a operação informada. Não representam, por si só, um resultado causado pela mentoria.</p></>}</>}{!validation && tab === 'records' && <section className="panel"><div className="panel-heading"><div><h2>Registros mensais</h2><p>{user.role === 'mentee' ? 'Versões compartilhadas pela equipe.' : 'Rascunhos da equipe e publicações, sem duplicar o mês da empresa.'}</p></div></div><ErrorBox error={records.error} />{records.isPending ? <Loading /> : !records.isError && (scopedRecords.length ? <div className="indicator-records">{scopedRecords.sort((a, b) => b.period.localeCompare(a.period)).map(r => <button key={r.id} onClick={() => go(`/indicators/${r.id}`)} className="indicator-record-row"><span className="indicator-month-icon"><BarChart3 size={19} /></span><span><strong>{monthLabel(r.period)}</strong><small>{r.sourceLabel || 'Origem ainda não publicada'}{r.publishedVersion ? ` · Versão ${r.publishedVersion}` : ''}</small></span><span className="badge neutral">{r.status === 'archived' ? 'Arquivado' : !r.publishedVersion ? 'Rascunho privado' : r.hasUnpublishedChanges && user.role !== 'mentee' ? 'Alterações não publicadas' : 'Publicado'}</span><PeriodBadge value={r.periodStatus} /><ChevronRight size={16} /></button>)}</div> : <Empty title="Nenhum registro neste intervalo" detail={canEdit ? 'Registre os números do mês. Campos que você ainda não conhece podem ficar vazios.' : 'Os resultados compartilhados aparecerão aqui.'} />)}</section>}{!validation && tab === 'goals' && <section className="panel indicator-goals-panel"><div className="panel-heading"><div><h2>Metas mensais</h2><p>Uma referência explícita para cada indicador. Meses parciais seguem em acompanhamento.</p></div>{canEdit && <Button onClick={() => setEditingGoal('new')}><Plus />Definir meta</Button>}</div><ErrorBox error={goals.error} />{goals.isPending ? <Loading /> : !goals.isError && <GoalList goals={scopedGoals} canEdit={!!canEdit} go={go} onEdit={setEditingGoal} notify={notify} highlightedId={params.get('goalId')} />}</section>}{tab === 'csv' && user.role !== 'mentee' && <CsvImport key={enrollmentId} enrollmentId={enrollmentId} clientName={client.name} enrollmentActive={client.status === 'active'} user={user} go={go} notify={notify} reportId={params.get('importId')} />}{canEdit && <><CreateRecord key={enrollmentId} open={creating} onOpenChange={setCreating} enrollmentId={enrollmentId} go={go} notify={notify} />{editingGoal && <GoalDialog enrollmentId={enrollmentId} initialPeriod={to} goal={editingGoal === 'new' ? undefined : editingGoal} onClose={() => setEditingGoal(null)} notify={notify} onSaved={(id, period) => go(`/indicators?enrollmentId=${enrollmentId}&period=${period}&goalId=${id}`)} />}</>}</>}</div>;}

function MetricCard({ metricKey, point }: { metricKey: MetricKey; point?: EvolutionPoint }) {
  const metric = point?.metrics?.[metricKey];
  return <section className="indicator-stat"><span>{indicatorMeta[metricKey].label}</span><strong>{formatMetric(metric?.value, metricKey)}</strong>{metric?.value === null || !metric ? <p>{reasonLabel(metric?.reason || 'missing_record')}</p> : <ComparisonText metricKey={metricKey} comparison={point?.comparison} />}</section>;
}
function ComparisonText({ metricKey, comparison }: { metricKey: MetricKey; comparison?: Comparison | null }) {
  const value = comparison?.metrics?.[metricKey];
  if (!comparison?.comparable || value?.absoluteChange == null) return <p className="indicator-comparison-note">{reasonLabel(value?.reason || comparison?.reason || 'missing_previous')}</p>;
  const change = value.absoluteChange;
  const prefix = change > 0 ? '+' : '';
  return <p className="indicator-comparison">{prefix}{indicatorMeta[metricKey].unit === 'percent' ? `${new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 2 }).format(change)} p.p.` : formatMetric(change, metricKey)}{value.percentChange != null ? ` (${value.percentChange > 0 ? '+' : ''}${new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 2 }).format(value.percentChange)}%)` : ''}<span>em relação ao mês anterior{value.reason === 'zero_baseline' ? ' · percentual não calculável sobre zero' : ''}</span></p>;
}

function EvolutionChart({ points, go, exportUrl }: { points: EvolutionPoint[]; go: (path: string) => void; exportUrl: string }) {
  const [metricKey, setMetricKey] = useState<MetricKey>('revenue');
  const values = points.map(p => p.metrics?.[metricKey]?.value ?? null); const known = values.filter((n): n is number => n !== null);
  const min = Math.min(0, ...known); const max = Math.max(1, ...known); const range = max - min || 1;
  const x = (i: number) => 84 + (points.length === 1 ? 270 : i * 540 / (points.length - 1)); const y = (v: number) => 210 - (v - min) / range * 160;
  const segments: string[] = []; let segment = '';
  points.forEach((point, index) => { const v = values[index]; const sameBasis = index === 0 || (!!point.comparison?.comparable && point.comparison.metrics?.[metricKey]?.absoluteChange != null); if (v === null || !sameBasis) { if (segment) segments.push(segment); segment = ''; } if (v !== null) segment += `${segment ? ' L' : 'M'}${x(index)},${y(v)}`; }); if (segment) segments.push(segment);
  return <section className="panel indicator-evolution"><div className="panel-heading"><div><h2>Evolução ao longo dos meses</h2><p>Linhas ligam somente meses fechados e comparáveis. Parciais e lacunas ficam separados.</p></div><a className="indicator-download" href={exportUrl} download><Download size={16} />Exportar evolução CSV</a><Field label="Indicador"><select value={metricKey} onChange={e => setMetricKey(e.target.value as MetricKey)}>{Object.entries(indicatorMeta).map(([key, m]) => <option key={key} value={key}>{m.label}</option>)}</select></Field></div>{known.length ? <div className="indicator-chart-wrap"><svg className="indicator-chart" viewBox="0 0 660 260" role="img" aria-label={`Evolução de ${indicatorMeta[metricKey].label}. ${known.length} meses informados. Os valores completos estão na tabela a seguir.`}><title>{indicatorMeta[metricKey].label} por mês</title>{[0, 0.5, 1].map(t => <g key={t}><line x1="84" x2="624" y1={y(min + t * range)} y2={y(min + t * range)} className="chart-grid" /><text x="75" y={y(min + t * range) + 4} textAnchor="end">{new Intl.NumberFormat('pt-BR', { notation: 'compact', maximumFractionDigits: 1 }).format(min + t * range)}</text></g>)}{segments.map((path, i) => <path key={i} d={path} className="chart-line" />)}{points.map((point, i) => <g key={point.period}>{values[i] !== null && <circle cx={x(i)} cy={y(values[i]!)} r="4.5" className={point.data?.periodStatus === 'partial' ? 'chart-point partial' : 'chart-point'}><title>{monthLabel(point.period)}: {formatMetric(values[i], metricKey)} · {point.data?.periodStatus === 'partial' ? 'Parcial' : 'Fechado'} · {point.data?.sourceLabel}</title></circle>}{(points.length < 10 || i === 0 || i === points.length - 1 || i % Math.ceil(points.length / 8) === 0) && <text x={x(i)} y="239" textAnchor="middle">{monthLabel(point.period, true)}</text>}</g>)}</svg><div className="indicator-chart-legend"><span><i />Mês fechado</span><span><i className="partial" />Parcial</span><span>{indicatorMeta[metricKey].unit === 'BRL' ? 'Valores em reais' : indicatorMeta[metricKey].unit === 'percent' ? 'Valores em %' : indicatorMeta[metricKey].unit === 'ratio' ? 'Múltiplo da base' : 'Quantidade'}</span></div></div> : <Empty title="Ainda não há dados para este indicador" detail="O gráfico aparecerá quando houver valores publicados que possam ser calculados." />}<div className="table-scroll"><table className="indicator-table"><caption className="sr-only">Valores mensais de {indicatorMeta[metricKey].label}</caption><thead><tr><th>Mês</th><th>Valor</th><th>Situação e base</th><th>Comparação com mês anterior</th><th><span className="sr-only">Registro</span></th></tr></thead><tbody>{points.map(p => <tr key={p.period}><th scope="row">{monthLabel(p.period, true)}</th><td><strong>{formatMetric(p.metrics?.[metricKey]?.value, metricKey)}</strong>{p.metrics?.[metricKey]?.reason && <small>{reasonLabel(p.metrics[metricKey]?.reason)}</small>}</td><td><PeriodBadge value={p.data?.periodStatus} /><small>{p.data?.sourceLabel || 'Sem publicação'}</small></td><td><ComparisonText metricKey={metricKey} comparison={p.comparison} /></td><td>{p.recordId && p.publishedVersion && <button className="text-button" onClick={() => go(`/indicators/${p.recordId}?version=${p.publishedVersion}`)}>Ver registro <ChevronRight size={13} /></button>}</td></tr>)}</tbody></table></div></section>;
}

type RecordForm = Omit<IndicatorContent, 'values'> & { values: Partial<Record<MetricKey, string>> };
function formFrom(content?: IndicatorContent): RecordForm { return { periodStatus: content?.periodStatus || 'partial', sourceLabel: content?.sourceLabel || '', notes: content?.notes || '', basisConfirmed: content?.basisConfirmed || false, adsAttributionConfirmed: content?.adsAttributionConfirmed || false, costsComplete: content?.costsComplete || false, values: Object.fromEntries(rawMetricKeys.map(key => [key, content?.values[key] == null ? '' : String(content.values[key]).replace('.', ',')])) }; }
function contentFrom(form: RecordForm): IndicatorContent { const values: IndicatorContent['values'] = {}; for (const key of rawMetricKeys) { const text = form.values[key]?.trim() || ''; if (indicatorMeta[key].unit === 'count') { if (text && (!/^\d+$/.test(text) || (!Number.isSafeInteger(Number(text)) || Number(text) > 1e9))) throw new Error(`${indicatorMeta[key].label}: informe uma quantidade inteira, sem casas decimais.`); values[key] = text ? Number(text) : null; } else values[key] = parseIndicatorDecimal(text, 2, indicatorMeta[key].label); } return { ...form, sourceLabel: form.sourceLabel.trim(), values }; }
function RecordFields({ form, onChange, period, disabled = false }: { form: RecordForm; onChange: (value: RecordForm) => void; period: string; disabled?: boolean }) {
  return <fieldset disabled={disabled} className="indicator-form-fields"><div className="form-grid"><Field label="Situação do mês" hint={period === currentMonth() ? 'O mês atual deve permanecer parcial.' : 'Feche somente quando os dados do mês estiverem consolidados.'}><select value={form.periodStatus} onChange={e => onChange({ ...form, periodStatus: e.target.value as 'partial' | 'closed' })}><option value="partial">Parcial · ainda em acompanhamento</option><option value="closed" disabled={period >= currentMonth()}>Fechado · dados consolidados</option></select></Field><Field label="Origem e base dos dados" hint="Mantenha o mesmo nome nos meses comparáveis. Ex.: Conta principal ML · vendas aprovadas."><input required minLength={3} maxLength={200} value={form.sourceLabel} onChange={e => onChange({ ...form, sourceLabel: e.target.value })} placeholder="Qual conta, relatório e base foram usados?" /></Field></div><p className="form-note"><Info size={15} />Deixe em branco o que ainda não foi informado. Use zero apenas quando o resultado observado for realmente zero.</p>{['Vendas e visitas', 'Publicidade e custos', 'Qualidade da operação', 'Estoque e anúncios'].map(group => <Disclosure key={group} className="indicator-field-group" defaultOpen title={group}><div className="indicator-values-grid">{rawMetricKeys.filter(key => indicatorMeta[key].group === group).map(key => <Field key={key} label={indicatorMeta[key].label} hint={indicatorMeta[key].unit === 'BRL' ? 'Reais · ex.: 1.234,56' : 'Quantidade inteira'}><input inputMode={indicatorMeta[key].unit === 'BRL' ? 'decimal' : 'numeric'} maxLength={24} value={form.values[key] || ''} onChange={e => onChange({ ...form, values: { ...form.values, [key]: e.target.value } })} placeholder="Não informado" /></Field>)}</div></Disclosure>)}<div className="indicator-basis-checks"><h3>Conferência da base</h3><label><input type="checkbox" checked={form.basisConfirmed} onChange={e => onChange({ ...form, basisConfirmed: e.target.checked })} /><span><strong>Os dados têm o mesmo escopo e base</strong><small>Mesma conta, período, critério de pedidos e universo dos valores relacionados.</small></span></label><label><input type="checkbox" checked={form.adsAttributionConfirmed} onChange={e => onChange({ ...form, adsAttributionConfirmed: e.target.checked })} /><span><strong>Publicidade com a mesma janela de atribuição</strong><small>Investimento e receita atribuída são comparáveis entre si neste mês.</small></span></label><label><input type="checkbox" checked={form.costsComplete} onChange={e => onChange({ ...form, costsComplete: e.target.checked })} /><span><strong>Custos totais completos, incluindo publicidade</strong><small>Confirme apenas se todos os custos considerados na margem estiverem informados.</small></span></label></div><Field label="Observações e contexto (opcional)"><textarea rows={3} maxLength={10000} value={form.notes || ''} onChange={e => onChange({ ...form, notes: e.target.value })} placeholder="Explique campanhas, sazonalidade, mudanças de base ou informações que ainda faltam." /></Field></fieldset>;
}
function CreateRecord({ open, onOpenChange, enrollmentId, go, notify }: { open: boolean; onOpenChange: (v: boolean) => void; enrollmentId: string; go: PageProps['go']; notify: PageProps['notify'] }) {
  const [period, setPeriod] = useState(currentMonth()); const [sourceLabel, setSourceLabel] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>(); const qc = useQueryClient();
  useEffect(() => { if (open) { setPeriod(currentMonth()); setSourceLabel(''); setError(null); } }, [open]);
  async function save(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setBusy(true); setError(null); try { const result = await post<{ id: string }>('/indicators', { enrollmentId, period, ...contentFrom({ ...formFrom(), sourceLabel, periodStatus: period === currentMonth() ? 'partial' : 'closed' }) }); await qc.invalidateQueries({ queryKey: ['indicators'] }); onOpenChange(false); notify('Registro mensal iniciado. Preencha os dados antes de publicar.'); go(`/indicators/${result.id}?edit=1`); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={open} onOpenChange={onOpenChange} title="Registrar resultados do mês" description="Um único registro consolidado por mês e contratação. O rascunho fica visível somente à equipe."><form className="form-stack" onSubmit={save}><Field label="Mês de referência"><input type="month" required max={currentMonth()} value={period} onChange={e => setPeriod(e.target.value)} /></Field><Field label="Origem e base dos dados" hint="Use um nome estável nos meses com a mesma base."><input required minLength={3} maxLength={200} value={sourceLabel} onChange={e => setSourceLabel(e.target.value)} placeholder="Ex.: Conta principal ML · vendas aprovadas" /></Field><p className="form-note">Os valores serão preenchidos na próxima tela. Campos vazios não serão tratados como zero.</p><ErrorBox error={error} /><div className="dialog-actions"><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button disabled={busy}>{busy && <LoaderCircle className="spin" />}Iniciar registro</Button></div></form></Dialog>;
}

function RecordDetail({ id, route, user, go, notify }: PageProps & { id: string }) {
  const params = new URLSearchParams(route.split('?')[1]); const version = params.get('version'); const staff = user.role !== 'mentee';
  const query = useQuery({ queryKey: ['indicator', id], queryFn: () => api<IndicatorRecord>(`/indicators/${id}`), refetchInterval: 30_000 });
  const revision = useQuery({ queryKey: ['indicator', id, 'revision', version], queryFn: () => api<IndicatorRecord>(`/indicators/${id}?version=${encodeURIComponent(version!)}`), enabled: !!version });
  const [tab, setTab] = useState(staff && params.get('edit') === '1' ? 'draft' : 'published'); const [statusOpen, setStatusOpen] = useState(false);
  const recordMotion = useMotionRegion(tab);
  useEffect(() => { if (version) setTab('published'); }, [version]);
  if (query.isPending) return <Loading />; if (query.isError || !query.data) return <ErrorBox error={query.error} />;
  const record = query.data; const snapshot = version ? revision.data?.published : record.published;
  return <><button className="back-link" onClick={() => go(`/indicators?enrollmentId=${record.enrollmentId}&period=${record.period}`)}><ArrowLeft size={16} />Voltar à evolução mensal</button><div className="page-title"><div><span className="eyebrow">{record.clientName} · INDICADORES MENSAIS</span><h1>{monthLabel(record.period)}</h1><p>{record.sourceType === 'csv' ? 'Importado via CSV' : 'Registro manual'} · {tab === 'draft' ? 'Preparação privada da equipe.' : 'Resultados compartilhados com contexto e origem.'}</p></div><div className="inline-actions">{record.status === 'archived' && <span className="badge neutral">Arquivado</span>}{staff && record.enrollmentStatus === 'active' && <Button variant="outline" onClick={() => setStatusOpen(true)}>{record.status === 'archived' ? 'Reativar registro' : 'Arquivar registro'}</Button>}</div></div><section ref={recordMotion} className="panel indicator-record-detail">{staff && <div className="tabs"><button className={tab === 'published' ? 'selected' : ''} onClick={() => setTab('published')}>Versão compartilhada</button><button className={tab === 'draft' ? 'selected' : ''} onClick={() => { setTab('draft'); if (version) go(`/indicators/${id}?edit=1`); }}><LockKeyhole size={13} />Preparar registro</button></div>}{tab === 'draft' && staff && record.draft ? <RecordEditor key={id} record={record} user={user} notify={notify} onPublished={() => { setTab('published'); go(`/indicators/${id}`); }} /> : <><div className="diagnosis-public-toolbar"><span><CheckCheck size={16} />Histórico de publicações</span>{record.revisions?.length > 0 && <Field label="Versão compartilhada"><select value={version || String(record.publishedVersion)} onChange={e => go(`/indicators/${id}?version=${e.target.value}`)}>{record.revisions.map(r => <option key={r.version} value={r.version}>Versão {r.version} · {dateLabel(r.publishedAt)}</option>)}</select></Field>}</div>{version && revision.isPending ? <Loading /> : version && revision.isError ? <ErrorBox error={revision.error} /> : snapshot ? <PublishedRecord snapshot={snapshot} sourceType={record.sourceType} /> : <Empty title="Este registro ainda não foi publicado" detail="A equipe está preparando os números e a base do mês." />}</>}</section>{staff && record.history && <RecordHistory history={record.history} />}{staff && <RecordStatusDialog open={statusOpen} onOpenChange={setStatusOpen} record={record} notify={notify} />}</>;
}
function PublishedRecord({ snapshot, sourceType }: { snapshot: Snapshot; sourceType: IndicatorRecord['sourceType'] }) {
  return <div className="indicator-published"><div className="indicator-source"><div><span className="eyebrow">ORIGEM E BASE</span><h2>{snapshot.sourceLabel}</h2><p>{sourceType === 'csv' ? 'Importado via CSV' : 'Informado manualmente'} · Versão {snapshot.version} · {dateLabel(snapshot.publishedAt)}</p></div><PeriodBadge value={snapshot.periodStatus} /></div>{snapshot.notes && <section className="indicator-context-note"><h3>Contexto do mês</h3><p>{snapshot.notes}</p></section>}<div className="indicator-confirmations"><span className={`badge ${snapshot.basisConfirmed ? 'green' : 'amber'}`}>{snapshot.basisConfirmed ? 'Escopo e base conferidos' : 'Base ainda não confirmada'}</span><span className={`badge ${snapshot.adsAttributionConfirmed ? 'green' : 'neutral'}`}>{snapshot.adsAttributionConfirmed ? 'Atribuição de publicidade conferida' : 'Atribuição não confirmada'}</span><span className={`badge ${snapshot.costsComplete ? 'green' : 'neutral'}`}>{snapshot.costsComplete ? 'Custos completos informados' : 'Custos ainda incompletos'}</span></div><div className="table-scroll"><table className="indicator-table"><thead><tr><th>Indicador</th><th>Resultado</th><th>Como interpretar</th></tr></thead><tbody>{Object.entries(indicatorMeta).map(([key, meta]) => { const metric = snapshot.metrics?.[key as MetricKey]; return <tr key={key}><th scope="row">{meta.label}</th><td><strong>{formatMetric(metric?.value, key)}</strong></td><td>{metric?.reason ? reasonLabel(metric.reason) : meta.group === 'Indicadores calculados' ? metricFormula[key] : 'Valor informado pela equipe.'}</td></tr>; })}</tbody></table></div></div>;
}
const metricFormula: Record<string, string> = { averageTicket: 'Faturamento ÷ pedidos.', conversionRate: 'Pedidos ÷ visitas × 100.', roas: 'Receita atribuída ÷ investimento em publicidade.', acos: 'Investimento em publicidade ÷ receita atribuída × 100.', tacos: 'Investimento em publicidade ÷ faturamento × 100.', estimatedMargin: '(Faturamento − custos totais) ÷ faturamento × 100. Margem estimada, conforme custos informados.' };
function RecordEditor({ record, user, notify, onPublished }: { record: IndicatorRecord; user: User; notify: PageProps['notify']; onPublished: () => void }) {
  const storageKey = `elo:indicator:${user.id}:${record.id}`;
  const [form, setForm] = useState(() => formFrom(record.draft)); const [baseVersion, setBaseVersion] = useState(record.draftVersion!); const [dirty, setDirty] = useState(false); const dirtyRef = useRef(false); const [reason, setReason] = useState('');
  const [busy, setBusy] = useState(''); const [error, setError] = useState<unknown>(); const [reloadOpen, setReloadOpen] = useState(false); const qc = useQueryClient(); const initialized = useRef(false);
  useEffect(() => { if (initialized.current) return; initialized.current = true; try { const raw = localStorage.getItem(storageKey); if (raw) { const saved = JSON.parse(raw); if (saved.form && Number.isInteger(saved.baseVersion)) { setForm(saved.form); setBaseVersion(saved.baseVersion); setReason(saved.reason || ''); dirtyRef.current = true; setDirty(true); } } } catch { /* Storage is optional; the server remains authoritative. */ } }, [storageKey]);
  useEffect(() => { if (!dirtyRef.current && record.draft) { setForm(formFrom(record.draft)); setBaseVersion(record.draftVersion!); } }, [record.draftVersion, record.draft]);
  function remember(next: RecordForm, nextReason = reason) { setForm(next); dirtyRef.current = true; setDirty(true); try { localStorage.setItem(storageKey, JSON.stringify({ form: next, baseVersion, reason: nextReason })); } catch { /* The form remains available in this tab. */ } }
  const conflict = baseVersion !== record.draftVersion; const writable = record.enrollmentStatus === 'active' && record.status !== 'archived';
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(null); setBusy('save'); try { const saved = await patch<{ draftVersion?: number }>(`/indicators/${record.id}`, { expectedVersion: baseVersion, ...contentFrom(form), ...(record.publishedVersion ? { reason: reason.trim() } : {}) }); dirtyRef.current = false; setDirty(false); setReason(''); setBaseVersion(saved.draftVersion || baseVersion + 1); try { localStorage.removeItem(storageKey); } catch { /* Storage may be unavailable. */ } await qc.invalidateQueries({ queryKey: ['indicator', record.id] }); await qc.invalidateQueries({ queryKey: ['indicators'] }); notify('Rascunho salvo. A versão compartilhada continua a mesma até publicar.'); } catch (err) { setError(err); } finally { setBusy(''); } }
  async function publish() { setError(null); setBusy('publish'); try { await post(`/indicators/${record.id}/publish`, { expectedVersion: baseVersion }); await qc.invalidateQueries(); notify('Resultados do mês publicados.'); onPublished(); } catch (err) { setError(err); } finally { setBusy(''); } }
  function reload() { dirtyRef.current = false; setDirty(false); setForm(formFrom(record.draft)); setBaseVersion(record.draftVersion!); setReason(''); setError(null); try { localStorage.removeItem(storageKey); } catch { /* Optional local draft. */ } setReloadOpen(false); }
  return <form className="indicator-editor" onSubmit={save}><div className="indicator-draft-note"><LockKeyhole size={19} /><div><strong>Rascunho privado da equipe</strong><p>{dirty ? 'Há alterações neste dispositivo ainda não salvas no registro.' : 'As alterações só ficam disponíveis ao mentorado depois da publicação.'}</p></div><span>Versão de trabalho {baseVersion}</span></div>{conflict && <div className="diagnosis-conflict"><CircleAlert size={20} /><div><strong>Este registro foi alterado por outra pessoa.</strong><p>Seu rascunho local foi preservado. Copie o que deseja manter e recarregue a versão salva para revisar antes de continuar.</p><Button type="button" variant="outline" size="sm" onClick={() => setReloadOpen(true)}>Recarregar versão salva</Button></div></div>}{!writable && <p className="form-note">Este registro está disponível para consulta. Reative o registro ou a contratação antes de editar.</p>}<RecordFields form={form} onChange={remember} period={record.period} disabled={!writable || !!busy} />{record.publishedVersion && <Field label="Motivo da correção" hint="Obrigatório ao alterar um mês que já foi compartilhado."><textarea required minLength={3} maxLength={2000} rows={2} value={reason} disabled={!writable || !!busy} onChange={e => { setReason(e.target.value); remember(form, e.target.value); }} /></Field>}<ErrorBox error={error} /><div className="indicator-save-actions"><span>{dirty ? 'Rascunho local preservado neste dispositivo' : record.publishedVersion ? `Versão pública atual: ${record.publishedVersion}` : 'Ainda não publicado'}</span><Button variant="outline" disabled={!writable || !dirty || conflict || !!busy}>{busy === 'save' ? <LoaderCircle className="spin" /> : <Save />}Salvar rascunho</Button><Button type="button" disabled={!writable || dirty || conflict || !!busy || !rawMetricKeys.some(key => form.values[key]?.trim())} onClick={publish}>{busy === 'publish' ? <LoaderCircle className="spin" /> : <Send />}Publicar resultados</Button></div><Dialog open={reloadOpen} onOpenChange={setReloadOpen} title="Recarregar o registro salvo" description="Esta ação substitui o rascunho deste dispositivo. Copie primeiro as informações que deseja manter."><div className="dialog-actions"><Button type="button" variant="outline" onClick={() => setReloadOpen(false)}>Continuar revisando</Button><Button type="button" onClick={reload}>Recarregar versão salva</Button></div></Dialog></form>;
}
function RecordStatusDialog({ open, onOpenChange, record, notify }: { open: boolean; onOpenChange: (v: boolean) => void; record: IndicatorRecord; notify: PageProps['notify'] }) {
  const [expectedVersion, setExpectedVersion] = useState(record.draftVersion); const [error, setError] = useState<unknown>(); const [busy, setBusy] = useState(false); const qc = useQueryClient();
  useEffect(() => { if (open) { setExpectedVersion(record.draftVersion); setError(null); } }, [open]);
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setBusy(true); setError(null); try { await post(`/indicators/${record.id}/status`, { expectedVersion, status: record.status === 'archived' ? 'active' : 'archived', reason: new FormData(e.currentTarget).get('reason') }); await qc.invalidateQueries(); onOpenChange(false); notify('Situação do registro atualizada.'); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={open} onOpenChange={onOpenChange} title={record.status === 'archived' ? 'Reativar registro mensal' : 'Arquivar registro mensal'} description="O histórico e as versões compartilhadas serão preservados."><form className="form-stack" onSubmit={submit}><Field label="Motivo"><textarea name="reason" required minLength={3} maxLength={2000} rows={3} /></Field><ErrorBox error={error} /><div className="dialog-actions"><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button><Button disabled={busy}>Confirmar alteração</Button></div></form></Dialog>;
}
function RecordHistory({ history }: { history: NonNullable<IndicatorRecord['history']> }) { const labels: Record<string, string> = { 'indicator.created': 'Registro iniciado', 'indicator.updated': 'Rascunho atualizado', 'indicator.published': 'Resultados publicados', 'indicator.archived': 'Registro arquivado', 'indicator.reactivated': 'Registro reativado' }; return <section className="panel indicator-history"><div className="panel-heading"><div><h2>Histórico da equipe</h2><p>Alterações e motivos preservados para consulta.</p></div></div><div className="timeline">{history.map(event => <div className="timeline-item" key={event.id}><span className="timeline-dot" /><div><strong>{labels[event.action] || event.action}</strong>{typeof event.details?.reason === 'string' && <p>{event.details.reason}</p>}<small>{dateLabel(event.createdAt)}{event.actorName ? ` · ${event.actorName}` : ''}</small></div></div>)}</div></section>; }

const goalStatusLabels = { not_informed: 'Resultado não informado', in_progress: 'Em acompanhamento', achieved: 'Meta atingida', not_achieved: 'Meta não atingida' };
function GoalList({ goals, canEdit, go, onEdit, notify, highlightedId }: { goals: IndicatorGoal[]; canEdit: boolean; go: PageProps['go']; onEdit: (g: IndicatorGoal) => void; notify: PageProps['notify']; highlightedId?: string | null }) {
  const [changing, setChanging] = useState<IndicatorGoal | null>(null); const [historyGoal, setHistoryGoal] = useState<IndicatorGoal | null>(null);
  return <>{goals.length ? <div className="indicator-goal-grid">{goals.sort((a, b) => b.period.localeCompare(a.period)).map(goal => { const result = goal.evaluation; return <article id={`goal-${goal.id}`} key={goal.id} className={`indicator-goal-card ${goal.id === highlightedId ? 'highlighted' : ''}`}><div className="indicator-goal-top"><span><Target size={17} />{monthLabel(goal.period, true)}</span><span className={`badge ${goal.status === 'archived' ? 'neutral' : result?.status === 'achieved' ? 'green' : result?.status === 'not_achieved' ? 'amber' : 'blue'}`}>{goal.status === 'archived' ? 'Meta arquivada' : goalStatusLabels[result?.status || 'not_informed']}</span></div><h3>{indicatorMeta[goal.metricKey]?.label || 'Indicador'}</h3><p className="indicator-goal-target">{goal.direction === 'at_least' ? 'Pelo menos' : 'No máximo'} <strong>{formatMetric(goal.target, goal.metricKey)}</strong></p><dl><dt>Resultado publicado</dt><dd>{formatMetric(result?.actual, goal.metricKey)}</dd>{result?.difference != null && <><dt>Diferença para a meta</dt><dd>{result.difference > 0 ? '+' : ''}{indicatorMeta[goal.metricKey].unit === 'percent' ? `${new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 4 }).format(result.difference)} p.p.` : formatMetric(result.difference, goal.metricKey)}</dd></>}</dl>{result?.status === 'in_progress' ? <p className="indicator-goal-note">Resultado parcial e provisório. A avaliação final depende do fechamento do mês.</p> : result?.actual == null ? <p className="indicator-goal-note">{reasonLabel(result?.reason || 'missing_record')}</p> : null}{goal.notes && <p className="indicator-goal-notes">{goal.notes}</p>}<div className="indicator-goal-actions">{goal.planId && <button className="text-button" onClick={() => go(`/plans/${goal.planId}`)}>Plano vinculado <ArrowRight size={13} /></button>}{canEdit && <><Button variant="outline" size="sm" onClick={() => onEdit(goal)} disabled={goal.status === 'archived'}><Pencil />Editar</Button><button className="text-button" onClick={() => setHistoryGoal(goal)}>Histórico</button><button className="text-button" onClick={() => setChanging(goal)}>{goal.status === 'archived' ? 'Reativar' : 'Arquivar'}</button></>}</div></article>; })}</div> : <Empty title="Nenhuma meta neste intervalo" detail="As metas mensais definem um valor e uma direção para acompanhar cada indicador." />}{canEdit && historyGoal && <GoalHistoryDialog goal={historyGoal} onClose={() => setHistoryGoal(null)} />}{canEdit && changing && <GoalStatusDialog goal={changing} onClose={() => setChanging(null)} notify={notify} />}</>;
}
function GoalHistoryDialog({ goal, onClose }: { goal: IndicatorGoal; onClose: () => void }) {
  const {open:dialogOpen,dismiss}=useDialogDismiss(onClose);const query = useQuery({ queryKey: ['indicator-goal', goal.id], queryFn: () => api<IndicatorGoal & { history: NonNullable<IndicatorRecord['history']> }>(`/indicator-goals/${goal.id}`) });
  return <Dialog open={dialogOpen} onOpenChange={open => { if (!open) dismiss(); }} title="Histórico da meta" description={`${indicatorMeta[goal.metricKey].label} · ${monthLabel(goal.period)}`}>{query.isPending ? <Loading /> : query.isError ? <ErrorBox error={query.error} /> : query.data && <div className="indicator-goal-history"><div className="timeline">{query.data.history?.map(event => <div className="timeline-item" key={event.id}><span className="timeline-dot" /><div><strong>{event.action}</strong>{typeof event.details?.reason === 'string' && <p>{event.details.reason}</p>}<small>{dateLabel(event.createdAt)}{event.actorName ? ` · ${event.actorName}` : ''}</small></div></div>)}</div></div>}</Dialog>;
}
function GoalDialog({ enrollmentId, initialPeriod, goal, onClose, notify, onSaved }: { enrollmentId: string; initialPeriod: string; goal?: IndicatorGoal; onClose: () => void; notify: PageProps['notify']; onSaved?: (id: string, period: string) => void }) {
  const {open:dialogOpen,dismiss}=useDialogDismiss(onClose);const plans = useQuery({ queryKey: ['plans'], queryFn: () => api<ActionPlan[]>('/plans') }); const activePlans = plans.data?.filter(p => p.enrollmentId === enrollmentId && p.status === 'active') || [];
  const [metricKey, setMetricKey] = useState<MetricKey>(goal?.metricKey || 'revenue'); const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>(); const qc = useQueryClient();
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setBusy(true); setError(null); const data = Object.fromEntries(new FormData(e.currentTarget)); try { const unit = indicatorMeta[metricKey].unit; const entered = String(data.target).trim(); const negative = entered.startsWith('-'); if (negative && metricKey !== 'estimatedMargin') throw new Error('Somente a margem estimada aceita uma meta negativa.'); let target: string | null; if (unit === 'count') { if (!/^\d+$/.test(entered)) throw new Error('Informe uma quantidade inteira, sem casas decimais.'); target = String(Number(entered)); } else { target = parseIndicatorDecimal(negative ? entered.slice(1) : entered, unit === 'BRL' ? 2 : 4, 'Meta'); if (negative && target) target = `-${target}`; } if (target === null) throw new Error('Informe o valor da meta. Zero também é uma meta válida.'); const payload = { ...data, metricKey, target, planId: data.planId || null }; const result = goal ? await patch<{ id?: string }>(`/indicator-goals/${goal.id}`, { ...payload, expectedVersion: goal.version }) : await post<{ id: string }>('/indicator-goals', { ...payload, enrollmentId }); await qc.invalidateQueries({ queryKey: ['indicator-goals'] }); await qc.invalidateQueries({ queryKey: ['indicator-evolution'] }); await qc.invalidateQueries({ queryKey: ['plan'] }); notify(goal ? 'Meta atualizada com o motivo registrado.' : 'Meta mensal definida.'); dismiss(); onSaved?.(goal?.id || result.id || '', String(data.period)); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={dialogOpen} onOpenChange={open => { if (!open) dismiss(); }} title={goal ? 'Editar meta mensal' : 'Definir meta mensal'} description="Uma meta por indicador e mês. O resultado considera somente o registro publicado da mesma contratação."><form className="form-stack" onSubmit={submit}><div className="form-grid"><Field label="Mês da meta"><input name="period" type="month" defaultValue={goal?.period || initialPeriod} required /></Field><Field label="Indicador"><select name="metricKey" value={metricKey} onChange={e => setMetricKey(e.target.value as MetricKey)}>{Object.entries(indicatorMeta).map(([key, m]) => <option key={key} value={key}>{m.label}</option>)}</select></Field></div><div className="form-grid"><Field label="Direção da meta"><select name="direction" defaultValue={goal?.direction || 'at_least'}><option value="at_least">Pelo menos · maior ou igual</option><option value="at_most">No máximo · menor ou igual</option></select></Field><Field label={`Valor ${indicatorMeta[metricKey].unit === 'BRL' ? '(R$)' : indicatorMeta[metricKey].unit === 'percent' ? '(%)' : indicatorMeta[metricKey].unit === 'ratio' ? '(vezes)' : '(quantidade)'}`} hint="Zero é um alvo válido. Informe o valor, sem o símbolo da unidade."><input name="target" inputMode="decimal" required maxLength={24} defaultValue={goal?.target.replace('.', ',')} placeholder="Ex.: 10" /></Field></div><Field label="Plano de ação relacionado (opcional)"><select name="planId" defaultValue={goal?.planId || ''}><option value="">Sem plano vinculado</option>{goal?.planId && !activePlans.some(p => p.id === goal.planId) && <option value={goal.planId}>Vínculo anterior · selecione um plano ativo ou remova</option>}{activePlans.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}</select></Field><Field label="Contexto da meta (opcional)"><textarea name="notes" rows={3} maxLength={10000} defaultValue={goal?.notes || ''} /></Field>{goal && <Field label="Motivo da alteração"><textarea name="reason" required minLength={3} maxLength={2000} rows={2} /></Field>}<ErrorBox error={error || plans.error} /><div className="dialog-actions"><Button type="button" variant="outline" onClick={dismiss}>Cancelar</Button><Button disabled={busy || plans.isPending || plans.isError}>{busy && <LoaderCircle className="spin" />}{goal ? 'Salvar meta' : 'Definir meta'}</Button></div></form></Dialog>;
}
function GoalStatusDialog({ goal, onClose, notify }: { goal: IndicatorGoal; onClose: () => void; notify: PageProps['notify'] }) {
  const {open:dialogOpen,dismiss}=useDialogDismiss(onClose);const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>(); const qc = useQueryClient();
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setBusy(true); setError(null); try { await post(`/indicator-goals/${goal.id}/status`, { expectedVersion: goal.version, status: goal.status === 'archived' ? 'active' : 'archived', reason: new FormData(e.currentTarget).get('reason') }); await qc.invalidateQueries({ queryKey: ['indicator-goals'] }); await qc.invalidateQueries({ queryKey: ['indicator-evolution'] }); await qc.invalidateQueries({ queryKey: ['plan'] }); dismiss(); notify('Situação da meta atualizada.'); } catch (err) { setError(err); } finally { setBusy(false); } }
  return <Dialog open={dialogOpen} onOpenChange={open => { if (!open) dismiss(); }} title={goal.status === 'archived' ? 'Reativar meta' : 'Arquivar meta'} description={`${indicatorMeta[goal.metricKey].label} · ${monthLabel(goal.period)}`}><form className="form-stack" onSubmit={submit}><Field label="Motivo"><textarea name="reason" required minLength={3} maxLength={2000} rows={3} /></Field><ErrorBox error={error} /><div className="dialog-actions"><Button type="button" variant="outline" onClick={dismiss}>Cancelar</Button><Button disabled={busy}>Confirmar alteração</Button></div></form></Dialog>;
}

type CsvIssue = { field: string; message: string };
type CsvResult = { version: number; columns: unknown[]; errors: CsvIssue[]; rows: { line: number; period?: string; data?: IndicatorContent & { period: string }; errors: CsvIssue[]; classification: 'create' | 'conflict' | 'invalid'; existingId?: string; existingStatus?: string }[]; counts: { create: number; conflict: number; invalid: number }; previewToken: string | null; expiresAt: string | null };
type ImportSummary = { id: string; enrollmentId: string; clientName: string; createdAt: string; createdByName: string; fileName?: string | null; counts: { total: number; imported: number; skipped: number; invalid: number }; duplicatePolicy: 'skip_existing' };
type ImportReport = ImportSummary & { rows: { line: number; period?: string; status: 'imported' | 'skipped' | 'invalid'; indicatorId?: string; existingId?: string; existingStatus?: string; errors: CsvIssue[] }[]; errors: CsvIssue[] };
type CsvSession = { csvText: string; fileName: string; preview: CsvResult | null; requestKey: string | null; attempted: boolean };
const blankCsvSession = (): CsvSession => ({ csvText: '', fileName: '', preview: null, requestKey: null, attempted: false });
function csvRequestKey() { if (typeof crypto.randomUUID === 'function') return crypto.randomUUID(); const b = crypto.getRandomValues(new Uint8Array(16)); b[6] = (b[6] & 15) | 64; b[8] = (b[8] & 63) | 128; const h = [...b].map(v => v.toString(16).padStart(2, '0')).join(''); return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`; }
function CsvImport({ enrollmentId, clientName, enrollmentActive, user, go, notify, reportId }: { enrollmentId: string; clientName: string; enrollmentActive: boolean; user: User; go: PageProps['go']; notify: PageProps['notify']; reportId: string | null }) {
  const queryClient = useQueryClient();
  const history = useQuery({ queryKey: ['indicator-imports', enrollmentId], queryFn: () => api<ImportSummary[]>(`/indicators/imports?enrollmentId=${encodeURIComponent(enrollmentId)}`), refetchInterval: 30_000 });
  const report = useQuery({ queryKey: ['indicator-import', enrollmentId, reportId], queryFn: () => api<ImportReport>(`/indicators/imports/${encodeURIComponent(reportId!)}`), enabled: !!reportId && history.isSuccess });
  const storageKey = `elo:csv-import:${user.id}:${enrollmentId}`;
  const [session, setSession] = useState<CsvSession>(blankCsvSession); const [restored, setRestored] = useState(false);
  const [error, setError] = useState<unknown>(); const [busy, setBusy] = useState<'read' | 'preview' | 'import' | ''>(''); const busyRef = useRef(false);
  const [confirmOpen, setConfirmOpen] = useState(false); const [acknowledged, setAcknowledged] = useState(false); const [permissionError, setPermissionError] = useState<unknown>();
  const [now, setNow] = useState(Date.now()); const revisionRef = useRef(0); const mounted = useRef(true); const fileRef = useRef<HTMLInputElement>(null);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  useEffect(() => { const timer = setInterval(() => setNow(Date.now()), 15_000); return () => clearInterval(timer); }, []);
  useEffect(() => { try { const saved = sessionStorage.getItem(storageKey); if (saved) { const value = JSON.parse(saved); if (typeof value.csvText === 'string' && typeof value.fileName === 'string' && new TextEncoder().encode(value.csvText).length <= 65536) { setSession({ csvText: value.csvText, fileName: value.fileName.slice(0, 150), preview: value.preview?.version === 1 && Array.isArray(value.preview.rows) ? value.preview : null, requestKey: typeof value.requestKey === 'string' ? value.requestKey : null, attempted: value.attempted === true }); } } } catch { /* The form works without browser storage. */ } setRestored(true); }, [storageKey]);
  function preserve(value: CsvSession) { try { if (value.csvText) sessionStorage.setItem(storageKey, JSON.stringify(value)); else sessionStorage.removeItem(storageKey); } catch { /* Network retries in the open tab still retain their key. */ } }
  useEffect(() => { if (restored) preserve(session); }, [session, restored, storageKey]);
  function update(text: string, fileName = '') { revisionRef.current++; setSession({ csvText: text, fileName, preview: null, requestKey: null, attempted: false }); setConfirmOpen(false); setAcknowledged(false); setError(null); }
  async function readFile(file?: File) {
    if (!file || busyRef.current) return;
    update(''); if (file.size > 65536) { setError('O CSV é muito grande. Use um arquivo de até 64 KiB e 200 linhas de dados.'); return; }
    const revision = revisionRef.current; busyRef.current = true; setBusy('read');
    try { const text = await file.text(); if (mounted.current && revision === revisionRef.current) update(text, file.name.slice(0, 150)); }
    catch { if (mounted.current) setError('Não foi possível ler o arquivo. Tente selecioná-lo novamente.'); }
    finally { busyRef.current = false; if (mounted.current) setBusy(''); }
  }
  function captureError(err: unknown) {
    if (err instanceof ApiError && (err.status === 403 || err.status === 404) && err.code !== 'CSV_PREVIEW_INVALID') setPermissionError(err);
    setError(err);
  }
  async function preview(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (busyRef.current) return; setError(null); setConfirmOpen(false); setAcknowledged(false);
    if (new TextEncoder().encode(session.csvText).length > 65536) { setError('O CSV é muito grande. Use até 64 KiB e 200 linhas de dados.'); return; }
    const revision = revisionRef.current; busyRef.current = true; setBusy('preview');
    setSession(current => ({ ...current, preview: null, requestKey: null, attempted: false }));
    try { const result = await post<CsvResult>('/indicators/csv-preview', { enrollmentId, csvText: session.csvText }); if (mounted.current && revision === revisionRef.current) setSession(current => ({ ...current, preview: result, requestKey: result.previewToken ? csvRequestKey() : null, attempted: false })); }
    catch (err) { if (mounted.current && revision === revisionRef.current) captureError(err); }
    finally { busyRef.current = false; if (mounted.current) setBusy(''); }
  }
  function downloadPreviewErrors() { if (!session.preview) return; const blob = new Blob([indicatorPreviewErrorsCsv(session.preview)], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'erros-previa-indicadores.csv'; document.body.appendChild(anchor); anchor.click(); anchor.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); }
  const result = session.preview; const expired = !!result?.expiresAt && new Date(result.expiresAt).getTime() <= now;
  const canConfirm = enrollmentActive && !!result?.previewToken && !!session.requestKey && result.counts.create > 0 && !result.errors.length && (!expired || session.attempted);
  async function confirm(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (busyRef.current || !canConfirm || !acknowledged || !result?.previewToken || !session.requestKey) return;
    const pending = { ...session, attempted: true }; setSession(pending); preserve(pending); busyRef.current = true; setBusy('import'); setError(null);
    try {
      const saved = await post<ImportReport>('/indicators/csv-import', { enrollmentId, csvText: pending.csvText, previewToken: result.previewToken, requestKey: pending.requestKey, confirmed: true, duplicatePolicy: 'skip_existing', ...(pending.fileName ? { fileName: pending.fileName } : {}) });
      queryClient.setQueryData(['indicator-import', enrollmentId, saved.id], saved);
      preserve(blankCsvSession());
      await Promise.all([queryClient.invalidateQueries({ queryKey: ['indicators'] }), queryClient.invalidateQueries({ queryKey: ['indicator-imports', enrollmentId] })]);
      if (mounted.current) { setSession(blankCsvSession()); setConfirmOpen(false); setAcknowledged(false); if (fileRef.current) fileRef.current.value = ''; notify(`${saved.counts.imported} ${saved.counts.imported === 1 ? 'rascunho importado' : 'rascunhos importados'}. Revise e publique cada mês quando estiver pronto.`); go(`/indicators?enrollmentId=${enrollmentId}&tab=csv&importId=${saved.id}`); }
    } catch (err) {
      if (mounted.current) {
        if (err instanceof ApiError && (err.status === 409 || err.code === 'CSV_PREVIEW_INVALID')) { setSession(current => ({ ...current, preview: current.preview ? { ...current.preview, previewToken: null } : null, requestKey: null, attempted: false })); setConfirmOpen(false); setAcknowledged(false); setError(new Error(`${err.message} Valide a prévia novamente antes de confirmar.`)); }
        else captureError(err instanceof ApiError ? err : new Error('A resposta da importação não foi recebida. A mesma tentativa foi preservada: tente novamente para recuperar o resultado, sem criar outro lote.'));
      }
    } finally { busyRef.current = false; if (mounted.current) setBusy(''); }
  }
  if (history.isPending || !restored) return <Loading />;
  if (history.isError || permissionError) return <ErrorBox error={permissionError || history.error} />;
  return <>{reportId && <section className="panel indicator-import-report">{report.isPending ? <Loading /> : report.isError ? <ErrorBox error={report.error} /> : report.data && (report.data.enrollmentId === enrollmentId ? <ImportReportView report={report.data} go={go} /> : <ErrorBox error="Este relatório pertence a outra contratação. Selecione a empresa correspondente para consultá-lo." />)}</section>}<section className="panel indicator-csv"><div className="panel-heading"><div><h2>Importar indicadores por CSV</h2><p>Valide o arquivo, confira o lote e confirme a criação dos rascunhos.</p></div><a className="indicator-download" href="/api/indicators/csv-template" download><Download size={16} />Baixar modelo CSV</a></div><div className="indicator-csv-content"><div className="indicator-csv-notice"><FileSpreadsheet size={22} /><div><strong>Somente meses novos e válidos serão importados</strong><p>Meses já cadastrados serão ignorados, inclusive rascunhos e registros arquivados. Todas as ocorrências de um mês repetido no arquivo serão inválidas. A publicação de cada mês continua sendo uma decisão da equipe.</p></div></div>{!enrollmentActive && <p className="form-note">A contratação precisa estar ativa para confirmar uma importação. O histórico continua disponível.</p>}{session.attempted && <div className="indicator-import-retry" role="status"><Info size={18} /><div><strong>Uma tentativa anterior está preservada</strong><p>Você pode repetir a mesma confirmação para recuperar o relatório. A chave da tentativa evita criar outro lote. Consulte também o histórico abaixo.</p></div></div>}<form className="form-stack" onSubmit={preview}><Field label="Selecionar arquivo CSV" hint="Até 64 KiB e 200 linhas de dados. Arquivo de texto UTF-8."><input ref={fileRef} type="file" accept=".csv,text/csv" disabled={!!busy} onChange={event => readFile(event.target.files?.[0])} /></Field>{session.fileName && <p className="indicator-selected-file">Arquivo selecionado: {session.fileName}</p>}<Field label="Conteúdo do CSV" hint="Você também pode colar e ajustar o conteúdo. Qualquer mudança exige uma nova validação."><textarea rows={8} value={session.csvText} disabled={!!busy} spellCheck={false} onChange={event => update(event.target.value)} placeholder="Cole aqui o conteúdo do modelo preenchido." /></Field>{!confirmOpen && <ErrorBox error={error} />}<div className="dialog-actions"><Button disabled={!!busy || !session.csvText.trim()}>{busy === 'preview' || busy === 'read' ? <LoaderCircle className="spin" /> : <CheckCheck />}{result ? 'Validar novamente' : 'Validar prévia'}</Button></div></form>{result && <div className="indicator-csv-results" aria-live="polite"><div className="indicator-import-section-title"><div><h3>Resultado da prévia</h3><p>Nenhum registro é gravado durante a validação.</p></div><div className="inline-actions">{result.expiresAt && <span className="badge neutral">{expired ? 'Prévia expirada' : `Válida até ${dateLabel(result.expiresAt)}`}</span>}{(result.counts.invalid > 0 || result.errors.length > 0) && <Button type="button" variant="outline" size="sm" onClick={downloadPreviewErrors}><Download />Baixar erros da prévia</Button>}</div></div><div className="indicator-csv-counts"><span><strong>{result.counts.create}</strong> linhas válidas para importar</span><span><strong>{result.counts.conflict}</strong> meses existentes · serão ignorados</span><span><strong>{result.counts.invalid}</strong> linhas inválidas · não serão importadas</span></div>{result.errors.length > 0 && <div className="error-box" role="alert"><CircleAlert size={17} /><ul>{result.errors.map((issue, index) => <li key={index}>{issue.message}</li>)}</ul></div>}{result.rows.length > 0 && <div className="table-scroll"><table className="indicator-table"><thead><tr><th>Linha / mês</th><th>Dados reconhecidos</th><th>Validação</th><th>Detalhes</th></tr></thead><tbody>{result.rows.map(row => <tr key={row.line}><th scope="row">Linha {row.line}<small>{row.period ? monthLabel(row.period, true) : 'Mês não reconhecido'}</small></th><td>{row.data ? <><strong>{row.data.sourceLabel}</strong><small>Faturamento: {formatMetric(row.data.values.revenue, 'revenue')}</small><small>Pedidos: {formatMetric(row.data.values.orders, 'orders')}</small></> : 'Dados inválidos'}</td><td><span className={`badge ${row.classification === 'create' ? 'green' : row.classification === 'conflict' ? 'amber' : 'red'}`}>{row.classification === 'create' ? 'Será importada como rascunho' : row.classification === 'conflict' ? 'Será ignorada' : 'Linha inválida'}</span></td><td>{row.errors.map((issue, index) => <p className="indicator-csv-issue" key={index}>{issue.message}</p>)}{row.classification === 'conflict' && <p className="indicator-csv-issue">O registro existente será preservado.</p>}{row.existingId && <button type="button" className="text-button" onClick={() => go(`/indicators/${row.existingId}`)}>Abrir registro existente <ChevronRight size={13} /></button>}{row.classification === 'create' && !row.errors.length && <span>Estrutura válida. Ainda não gravado.</span>}</td></tr>)}</tbody></table></div>}<div className="indicator-import-confirm-bar"><p>{!result.counts.create ? 'Não há linhas novas e válidas para importar.' : result.errors.length ? 'Corrija os problemas gerais do arquivo antes de continuar.' : expired && !session.attempted ? 'A prévia expirou. Valide novamente para conferir o estado atual dos registros.' : 'Confira as linhas e a empresa antes de confirmar.'}</p><Button disabled={!canConfirm || !!busy} onClick={() => { setAcknowledged(false); setError(null); setConfirmOpen(true); }}>{session.attempted ? <History /> : <Upload />}{session.attempted ? 'Retomar a mesma tentativa' : 'Revisar e confirmar'}</Button></div></div>}</div></section><section className="panel indicator-import-history"><div className="panel-heading"><div><h2>Histórico de importações</h2><p>Lotes desta contratação, com o resultado registrado no momento do envio.</p></div><History size={19} /></div>{history.data?.length ? <div className="indicator-import-history-list">{history.data.map(batch => <button className={`indicator-import-history-row ${reportId === batch.id ? 'selected' : ''}`} key={batch.id} onClick={() => go(`/indicators?enrollmentId=${enrollmentId}&tab=csv&importId=${batch.id}`)}><span className="indicator-month-icon"><FileSpreadsheet size={19} /></span><span><strong>{batch.fileName || 'CSV colado na plataforma'}</strong><small>{dateLabel(batch.createdAt)} · {batch.createdByName}</small><small>{batch.counts.imported} importadas · {batch.counts.skipped} ignoradas · {batch.counts.invalid} inválidas</small></span><span className="text-button">Ver relatório <ChevronRight size={14} /></span></button>)}</div> : <p className="small-empty">Nenhuma importação registrada para esta contratação.</p>}</section><Dialog open={confirmOpen} onOpenChange={open => { if (busy !== 'import') setConfirmOpen(open); }} title="Confirmar importação de indicadores" description="Os meses existentes serão preservados e nenhum resultado será publicado automaticamente."><form className="form-stack" onSubmit={confirm}><div className="indicator-import-company"><span>EMPRESA / CONTRATAÇÃO</span><strong>{clientName}</strong>{session.fileName && <small>{session.fileName}</small>}</div><div className="indicator-csv-counts"><span><strong>{result?.counts.create ?? 0}</strong> rascunhos a criar</span><span><strong>{result?.counts.conflict ?? 0}</strong> linhas ignoradas</span><span><strong>{result?.counts.invalid ?? 0}</strong> linhas inválidas</span></div><label className="indicator-import-ack"><input type="checkbox" checked={acknowledged} onChange={event => setAcknowledged(event.target.checked)} disabled={busy === 'import'} required /><span>Entendo que somente as linhas novas e válidas virarão rascunhos privados desta empresa. Vou revisar e publicar cada mês quando os dados estiverem prontos.</span></label><ErrorBox error={error} /><div className="dialog-actions"><Button type="button" variant="outline" disabled={busy === 'import'} onClick={() => setConfirmOpen(false)}>Voltar à prévia</Button><Button disabled={!acknowledged || !canConfirm || !!busy}>{busy === 'import' ? <LoaderCircle className="spin" /> : <Upload />}{busy === 'import' ? 'Importando…' : session.attempted ? 'Repetir a mesma tentativa' : 'Confirmar importação'}</Button></div></form></Dialog></>;
}
function ImportReportView({ report, go }: { report: ImportReport; go: PageProps['go'] }) {
  return <><div className="panel-heading"><div><h2>Relatório da importação</h2><p>{report.clientName} · {dateLabel(report.createdAt)} · {report.createdByName}</p></div><a className="indicator-download" href={`/api/indicators/imports/${encodeURIComponent(report.id)}/report.csv`} download><Download size={16} />Baixar relatório CSV</a></div><div className="indicator-import-report-content"><div className="indicator-import-success"><CheckCheck size={22} /><div><strong>{report.counts.imported} {report.counts.imported === 1 ? 'rascunho criado' : 'rascunhos criados'}</strong><p>Revise os meses importados e publique cada um quando estiver pronto. Meses existentes e linhas inválidas não foram alterados.</p>{report.fileName && <small>Arquivo: {report.fileName}</small>}</div></div><div className="indicator-csv-counts"><span><strong>{report.counts.imported}</strong> importadas de {report.counts.total} linhas</span><span><strong>{report.counts.skipped}</strong> ignoradas · registros preservados</span><span><strong>{report.counts.invalid}</strong> inválidas · nenhuma gravação</span></div>{report.errors.length > 0 && <div className="error-box"><CircleAlert size={17} /><ul>{report.errors.map((issue, index) => <li key={index}>{issue.message}</li>)}</ul></div>}<div className="table-scroll"><table className="indicator-table"><thead><tr><th>Linha / mês</th><th>Resultado do envio</th><th>Detalhes</th><th>Abrir registro</th></tr></thead><tbody>{report.rows.map(row => <tr key={row.line}><th scope="row">Linha {row.line}<small>{row.period ? monthLabel(row.period, true) : 'Mês não reconhecido'}</small></th><td><span className={`badge ${row.status === 'imported' ? 'green' : row.status === 'skipped' ? 'amber' : 'red'}`}>{row.status === 'imported' ? 'Importada como rascunho' : row.status === 'skipped' ? 'Ignorada · mês existente' : 'Inválida'}</span></td><td>{row.errors.map((issue, index) => <p className="indicator-csv-issue" key={index}>{issue.message}</p>)}{row.status === 'imported' ? 'Rascunho criado no momento desta importação.' : row.status === 'skipped' ? 'O registro existente foi preservado.' : !row.errors.length ? 'Linha não importada.' : null}</td><td>{(row.indicatorId || row.existingId) && <button className="text-button" onClick={() => go(`/indicators/${row.indicatorId || row.existingId}`)}>Abrir registro <ChevronRight size={13} /></button>}</td></tr>)}</tbody></table></div><p className="indicator-import-footnote">Este relatório preserva o resultado do envio. A situação atual de cada mês pode mudar após revisão e publicação.</p></div></>;
}
export function ClientIndicators({ enrollmentId, go }: { enrollmentId: string; go: PageProps['go'] }) {
  const query = useQuery({ queryKey: ['indicators', enrollmentId], queryFn: () => api<IndicatorRecord[]>(`/indicators?enrollmentId=${encodeURIComponent(enrollmentId)}`) });
  const latest = query.data?.filter(r => r.enrollmentId === enrollmentId && r.status !== 'archived' && r.publishedVersion).sort((a, b) => b.period.localeCompare(a.period))[0];
  return <section className="panel client-indicators-panel"><div className="panel-heading"><div><h2>Indicadores do negócio</h2><p>Resultados mensais informados e metas por contratação.</p></div><Button variant="outline" size="sm" onClick={() => go(`/indicators?enrollmentId=${enrollmentId}`)}><BarChart3 />Abrir evolução</Button></div><ErrorBox error={query.error} />{query.isPending ? <Loading /> : !query.isError && (latest ? <div className="client-indicator-summary"><div><span className="eyebrow">ÚLTIMO MÊS COMPARTILHADO</span><strong>{monthLabel(latest.period)}</strong><small>{latest.sourceLabel}</small><PeriodBadge value={latest.periodStatus} /></div>{(['revenue', 'orders', 'conversionRate'] as MetricKey[]).map(key => <div key={key}><span>{indicatorMeta[key].label}</span><strong>{formatMetric(latest.metrics?.[key]?.value, key)}</strong></div>)}</div> : <p className="small-empty">Ainda não há resultados mensais publicados. Consulte o painel para acompanhar os registros e as metas.</p>)}</section>;
}
